# Adaptive Rejection Sampling (ARS) Implementation
# Based on Gilks, W. R., & Wild, P. (1992)
# Adaptive rejection sampling for Gibbs sampling
# Journal of the Royal Statistical Society: Series C (Applied Statistics), 41(2), 337-348.

#' Compute log-density and its derivative at a point
#' @param f The density function (possibly unnormalized)
#' @param x Point at which to evaluate
#' @param h Small step size for numerical differentiation
#' @return List with h (log-density) and dh (derivative of log-density)
compute_log_density_and_derivative <- function(f, x, h = 1e-6) {
  # Evaluate log-density
  fx <- f(x)
  if (any(fx <= 0)) {
    stop("Density function returned non-positive value at x = ", x)
  }
  log_fx <- log(fx)

  # Numerical derivative using central difference
  fx_plus <- f(x + h)
  fx_minus <- f(x - h)

  if (any(fx_plus <= 0) || any(fx_minus <= 0)) {
    # Fall back to forward difference
    fx_plus <- f(x + h)
    if (any(fx_plus <= 0)) {
      stop("Cannot compute derivative: density not positive near x = ", x)
    }
    derivative <- (log(fx_plus) - log_fx) / h
  } else {
    # Central difference
    derivative <- (log(fx_plus) - log(fx_minus)) / (2 * h)
  }

  list(h = log_fx, dh = derivative)
}

#' Check log-concavity at a new point
#' @param x_new New point to check
#' @param x_points Existing abscissae points
#' @param h_values Log-density values at existing points
#' @param dh_values Derivatives at existing points
#' @return TRUE if log-concave, FALSE otherwise
check_log_concavity <- function(x_new, x_points, h_values, dh_values) {
  # Find the two nearest points
  if (length(x_points) < 2) return(TRUE)

  # Find where x_new would be inserted
  idx <- findInterval(x_new, x_points)

  if (idx == 0) {
    # x_new is less than all points - check with first two
    i <- 1
    j <- 2
  } else if (idx == length(x_points)) {
    # x_new is greater than all points - check with last two
    i <- length(x_points) - 1
    j <- length(x_points)
  } else {
    # x_new is between points
    i <- idx
    j <- idx + 1
  }

  # Check if the derivative is decreasing (necessary for log-concavity)
  # At point i, compute what the derivative should be if log-concave
  # The tangent line at i should be above the function at j
  expected_h_j <- h_values[i] + dh_values[i] * (x_points[j] - x_points[i])

  if (h_values[j] > expected_h_j + 1e-6) {
    return(FALSE)
  }

  # Check that derivatives are non-increasing
  if (i > 1 && dh_values[i] > dh_values[i-1] + 1e-6) {
    return(FALSE)
  }

  TRUE
}

#' Compute intersection of two tangent lines
#' @param x1, h1, dh1 First point and its log-density and derivative
#' @param x2, h2, dh2 Second point and its log-density and derivative
#' @return x-coordinate of intersection
compute_intersection <- function(x1, h1, dh1, x2, h2, dh2) {
  # Two lines: h1 + dh1*(x - x1) = h2 + dh2*(x - x2)
  # Solve for x
  if (abs(dh1 - dh2) < 1e-10) {
    # Lines are parallel, return midpoint
    return((x1 + x2) / 2)
  }
  x <- (h2 - h1 + dh1*x1 - dh2*x2) / (dh1 - dh2)
  return(x)
}

#' Evaluate upper envelope (piecewise linear upper bound)
#' @param x Point at which to evaluate
#' @param x_points Abscissae points
#' @param h_values Log-density values
#' @param dh_values Derivative values
#' @param z_points Intersection points
#' @return Value of upper envelope at x
evaluate_upper_envelope <- function(x, x_points, h_values, dh_values, z_points) {
  k <- length(x_points)

  # Find which segment x belongs to
  idx <- findInterval(x, z_points)

  if (idx == 0) {
    # Before first intersection - extrapolate from first point
    return(h_values[1] + dh_values[1] * (x - x_points[1]))
  } else if (idx == length(z_points)) {
    # After last intersection - extrapolate from last point
    return(h_values[k] + dh_values[k] * (x - x_points[k]))
  } else {
    # Between intersections - use corresponding tangent line
    return(h_values[idx] + dh_values[idx] * (x - x_points[idx]))
  }
}

#' Evaluate lower envelope (piecewise linear lower bound)
#' @param x Point at which to evaluate
#' @param x_points Abscissae points
#' @param h_values Log-density values
#' @return Value of lower envelope at x
evaluate_lower_envelope <- function(x, x_points, h_values) {
  k <- length(x_points)

  if (k < 2) {
    return(-Inf)  # No lower envelope with less than 2 points
  }

  # Find which segment x belongs to
  idx <- findInterval(x, x_points)

  if (idx == 0 || idx == k) {
    # Outside the range of x_points
    return(-Inf)
  }

  # Linear interpolation between points
  x1 <- x_points[idx]
  x2 <- x_points[idx + 1]
  h1 <- h_values[idx]
  h2 <- h_values[idx + 1]

  return(h1 + (h2 - h1) * (x - x1) / (x2 - x1))
}

#' Sample from the upper envelope
#' @param x_points Abscissae points
#' @param h_values Log-density values
#' @param dh_values Derivative values
#' @param z_points Intersection points
#' @param domain Domain of the distribution (left, right)
#' @return A sample from the upper envelope
sample_upper_envelope <- function(x_points, h_values, dh_values, z_points, domain) {
  k <- length(x_points)

  # Compute normalization constants for each segment
  # Each segment is an exponential of a linear function
  z_extended <- c(domain[1], z_points, domain[2])

  # Compute integral of exp(upper envelope) for each segment
  integrals <- numeric(k)
  for (i in 1:k) {
    z_left <- z_extended[i]
    z_right <- z_extended[i + 1]

    # Handle infinite bounds
    if (is.infinite(z_left)) z_left <- x_points[1] - 10
    if (is.infinite(z_right)) z_right <- x_points[k] + 10

    # Integral of exp(a + b*x) from z_left to z_right
    a <- h_values[i] - dh_values[i] * x_points[i]
    b <- dh_values[i]

    if (abs(b) < 1e-10) {
      # b ≈ 0: integral is exp(a) * (z_right - z_left)
      integrals[i] <- exp(a) * (z_right - z_left)
    } else {
      # Integral is exp(a)/b * (exp(b*z_right) - exp(b*z_left))
      integrals[i] <- exp(a) / b * (exp(b * z_right) - exp(b * z_left))
    }
  }

  # Sample segment proportional to integrals
  probs <- integrals / sum(integrals)
  segment <- sample(1:k, 1, prob = probs)

  # Sample from the chosen segment
  z_left <- z_extended[segment]
  z_right <- z_extended[segment + 1]

  if (is.infinite(z_left)) z_left <- x_points[1] - 10
  if (is.infinite(z_right)) z_right <- x_points[k] + 10

  a <- h_values[segment] - dh_values[segment] * x_points[segment]
  b <- dh_values[segment]

  # Inverse transform sampling
  u <- runif(1)

  if (abs(b) < 1e-10) {
    # Uniform distribution
    x_sample <- z_left + u * (z_right - z_left)
  } else {
    # Exponential distribution
    exp_left <- exp(b * z_left)
    exp_right <- exp(b * z_right)
    x_sample <- log(exp_left + u * (exp_right - exp_left)) / b
  }

  return(x_sample)
}

#' Adaptive Rejection Sampling
#' @param n Number of samples to generate
#' @param f Density function (possibly unnormalized), must be vectorized
#' @param domain Vector of length 2 specifying the domain (left, right)
#' @param x_init Initial abscissae points (at least 2 points required)
#' @param ... Additional arguments passed to f
#' @return Vector of n samples from the distribution
#' @export
ars <- function(n, f, domain = c(-Inf, Inf), x_init = NULL, ...) {
  # Input validation
  if (!is.numeric(n) || length(n) != 1 || n <= 0 || n != as.integer(n)) {
    stop("n must be a positive integer")
  }

  if (!is.function(f)) {
    stop("f must be a function")
  }

  if (!is.numeric(domain) || length(domain) != 2 || domain[1] >= domain[2]) {
    stop("domain must be a numeric vector of length 2 with domain[1] < domain[2]")
  }

  # Initialize abscissae points if not provided
  if (is.null(x_init)) {
    # Choose initial points based on domain
    if (is.finite(domain[1]) && is.finite(domain[2])) {
      x_init <- seq(domain[1] + 0.1 * diff(domain), 
                    domain[2] - 0.1 * diff(domain), 
                    length.out = 5)
    } else if (is.finite(domain[1]) && is.infinite(domain[2])) {
      x_init <- domain[1] + c(0.1, 1, 2, 5, 10)
    } else if (is.infinite(domain[1]) && is.finite(domain[2])) {
      x_init <- domain[2] - c(10, 5, 2, 1, 0.1)
    } else {
      x_init <- c(-5, -1, 0, 1, 5)
    }
  }

  if (length(x_init) < 2) {
    stop("At least 2 initial points required")
  }

  # Sort initial points
  x_init <- sort(x_init)

  # Check that initial points are within domain
  if (any(x_init <= domain[1]) || any(x_init >= domain[2])) {
    stop("Initial points must be strictly within the domain")
  }

  # Test that f is vectorized by checking if it returns correct length
  test_vals <- f(x_init, ...)
  if (length(test_vals) != length(x_init)) {
    stop("Function f must be vectorized (return vector of same length as input)")
  }

  if (any(test_vals <= 0)) {
    stop("Density function must be positive at all initial points")
  }

  # Initialize
  x_points <- x_init
  k <- length(x_points)
  h_values <- numeric(k)
  dh_values <- numeric(k)

  # Compute log-densities and derivatives at initial points
  for (i in 1:k) {
    result <- compute_log_density_and_derivative(function(x) f(x, ...), x_points[i])
    h_values[i] <- result$h
    dh_values[i] <- result$dh
  }

  # Check that derivatives are non-increasing (log-concavity check)
  if (any(diff(dh_values) > 1e-6)) {
    stop("Function does not appear to be log-concave at initial points. Derivatives should be non-increasing.")
  }

  # Compute intersection points (z values)
  z_points <- numeric(k - 1)
  for (i in 1:(k-1)) {
    z_points[i] <- compute_intersection(x_points[i], h_values[i], dh_values[i],
                                        x_points[i+1], h_values[i+1], dh_values[i+1])
  }

  # Sampling loop
  samples <- numeric(n)
  n_accepted <- 0
  n_iterations <- 0
  max_iterations <- n * 1000  # Safety limit

  while (n_accepted < n && n_iterations < max_iterations) {
    n_iterations <- n_iterations + 1

    # Sample from upper envelope
    x_star <- sample_upper_envelope(x_points, h_values, dh_values, z_points, domain)

    # Evaluate envelopes at x_star
    u_star <- evaluate_upper_envelope(x_star, x_points, h_values, dh_values, z_points)
    l_star <- evaluate_lower_envelope(x_star, x_points, h_values)

    # Evaluate true log-density at x_star
    result <- compute_log_density_and_derivative(function(x) f(x, ...), x_star)
    h_star <- result$h
    dh_star <- result$dh

    # Squeezing test (accept without evaluating true density)
    w <- runif(1)
    if (log(w) <= l_star - u_star) {
      # Accept
      n_accepted <- n_accepted + 1
      samples[n_accepted] <- x_star
    } else {
      # Rejection test
      if (log(w) <= h_star - u_star) {
        # Accept
        n_accepted <- n_accepted + 1
        samples[n_accepted] <- x_star
      }

      # Update envelopes by adding x_star to abscissae
      # Check log-concavity before adding
      if (!check_log_concavity(x_star, x_points, h_values, dh_values)) {
        stop("Non-log-concave density detected at x = ", x_star, 
             ". The function must be log-concave for ARS to work.")
      }

      # Insert x_star in sorted order
      insert_idx <- findInterval(x_star, x_points) + 1
      x_points <- c(x_points[1:(insert_idx-1)], x_star, x_points[insert_idx:length(x_points)])
      h_values <- c(h_values[1:(insert_idx-1)], h_star, h_values[insert_idx:length(h_values)])
      dh_values <- c(dh_values[1:(insert_idx-1)], dh_star, dh_values[insert_idx:length(dh_values)])

      # Recompute intersection points
      k <- length(x_points)
      z_points <- numeric(k - 1)
      for (i in 1:(k-1)) {
        z_points[i] <- compute_intersection(x_points[i], h_values[i], dh_values[i],
                                            x_points[i+1], h_values[i+1], dh_values[i+1])
      }
    }
  }

  if (n_iterations >= max_iterations) {
    warning("Maximum iterations reached. Only ", n_accepted, " samples generated.")
    samples <- samples[1:n_accepted]
  }

  return(samples)
}

#' Test function for ARS implementation
#' @export
test <- function() {
  cat("\n========================================\n")
  cat("ADAPTIVE REJECTION SAMPLING - TEST SUITE\n")
  cat("========================================\n\n")

  # Test 1: Input validation
  cat("TEST 1: Input validation\n")
  test1_passed <- TRUE

  # Test invalid n
  tryCatch({
    ars(-5, dnorm)
    test1_passed <- FALSE
    cat("  - Failed to catch negative n\n")
  }, error = function(e) {
    cat("  - Correctly rejected negative n\n")
  })

  tryCatch({
    ars(5.5, dnorm)
    test1_passed <- FALSE
    cat("  - Failed to catch non-integer n\n")
  }, error = function(e) {
    cat("  - Correctly rejected non-integer n\n")
  })

  # Test invalid function
  tryCatch({
    ars(10, "not a function")
    test1_passed <- FALSE
    cat("  - Failed to catch non-function\n")
  }, error = function(e) {
    cat("  - Correctly rejected non-function input\n")
  })

  # Test invalid domain
  tryCatch({
    ars(10, dnorm, domain = c(5, 2))
    test1_passed <- FALSE
    cat("  - Failed to catch invalid domain\n")
  }, error = function(e) {
    cat("  - Correctly rejected invalid domain\n")
  })

  if (test1_passed) {
    cat("TEST 1: PASS\n\n")
  } else {
    cat("TEST 1: FAIL\n\n")
  }

  # Test 2: Standard normal distribution
  cat("TEST 2: Standard normal distribution N(0,1)\n")
  set.seed(123)
  n_samples <- 5000
  samples_norm <- ars(n_samples, dnorm, domain = c(-10, 10))

  # Save samples to file
  write.table(samples_norm, "/app/normal_samples.txt", 
              row.names = FALSE, col.names = FALSE)
  cat("  - Generated", length(samples_norm), "samples\n")
  cat("  - Saved to /app/normal_samples.txt\n")

  # Statistical tests
  sample_mean <- mean(samples_norm)
  sample_sd <- sd(samples_norm)
  cat("  - Sample mean:", round(sample_mean, 4), "(expected: 0)\n")
  cat("  - Sample SD:", round(sample_sd, 4), "(expected: 1)\n")

  # Kolmogorov-Smirnov test
  ks_result <- ks.test(samples_norm, "pnorm")
  cat("  - K-S test p-value:", round(ks_result$p.value, 4), "\n")

  test2_passed <- (abs(sample_mean) < 0.05 && abs(sample_sd - 1) < 0.05 && 
                   ks_result$p.value > 0.05)

  if (test2_passed) {
    cat("TEST 2: PASS\n\n")
  } else {
    cat("TEST 2: FAIL\n\n")
  }

  # Test 3: Exponential distribution
  cat("TEST 3: Exponential distribution Exp(1)\n")
  set.seed(456)
  samples_exp <- ars(n_samples, dexp, domain = c(0.001, 20), 
                     x_init = c(0.1, 0.5, 1, 2, 5))

  # Save samples to file
  write.table(samples_exp, "/app/exponential_samples.txt", 
              row.names = FALSE, col.names = FALSE)
  cat("  - Generated", length(samples_exp), "samples\n")
  cat("  - Saved to /app/exponential_samples.txt\n")

  sample_mean <- mean(samples_exp)
  sample_sd <- sd(samples_exp)
  cat("  - Sample mean:", round(sample_mean, 4), "(expected: 1)\n")
  cat("  - Sample SD:", round(sample_sd, 4), "(expected: 1)\n")

  ks_result <- ks.test(samples_exp, "pexp")
  cat("  - K-S test p-value:", round(ks_result$p.value, 4), "\n")

  test3_passed <- (abs(sample_mean - 1) < 0.05 && abs(sample_sd - 1) < 0.1 && 
                   ks_result$p.value > 0.05)

  if (test3_passed) {
    cat("TEST 3: PASS\n\n")
  } else {
    cat("TEST 3: FAIL\n\n")
  }

  # Test 4: Gamma distribution
  cat("TEST 4: Gamma distribution Gamma(3, 1)\n")
  set.seed(789)
  dgamma_3_1 <- function(x) dgamma(x, shape = 3, rate = 1)
  samples_gamma <- ars(n_samples, dgamma_3_1, domain = c(0.001, 20),
                       x_init = c(0.5, 1, 2, 4, 6))

  sample_mean <- mean(samples_gamma)
  sample_sd <- sd(samples_gamma)
  expected_mean <- 3  # shape / rate
  expected_sd <- sqrt(3)  # sqrt(shape / rate^2)

  cat("  - Generated", length(samples_gamma), "samples\n")
  cat("  - Sample mean:", round(sample_mean, 4), "(expected:", expected_mean, ")\n")
  cat("  - Sample SD:", round(sample_sd, 4), "(expected:", round(expected_sd, 4), ")\n")

  ks_result <- ks.test(samples_gamma, function(x) pgamma(x, shape = 3, rate = 1))
  cat("  - K-S test p-value:", round(ks_result$p.value, 4), "\n")

  test4_passed <- (abs(sample_mean - expected_mean) < 0.1 && 
                   abs(sample_sd - expected_sd) < 0.15 && 
                   ks_result$p.value > 0.05)

  if (test4_passed) {
    cat("TEST 4: PASS\n\n")
  } else {
    cat("TEST 4: FAIL\n\n")
  }

  # Test 5: Beta distribution (only log-concave for certain parameters)
  cat("TEST 5: Beta distribution Beta(2, 2)\n")
  set.seed(321)
  dbeta_2_2 <- function(x) dbeta(x, 2, 2)
  samples_beta <- ars(1000, dbeta_2_2, domain = c(0.001, 0.999),
                      x_init = c(0.2, 0.4, 0.5, 0.6, 0.8))

  sample_mean <- mean(samples_beta)
  expected_mean <- 0.5  # alpha / (alpha + beta)

  cat("  - Generated", length(samples_beta), "samples\n")
  cat("  - Sample mean:", round(sample_mean, 4), "(expected:", expected_mean, ")\n")

  ks_result <- ks.test(samples_beta, function(x) pbeta(x, 2, 2))
  cat("  - K-S test p-value:", round(ks_result$p.value, 4), "\n")

  test5_passed <- (abs(sample_mean - expected_mean) < 0.05 && 
                   ks_result$p.value > 0.05)

  if (test5_passed) {
    cat("TEST 5: PASS\n\n")
  } else {
    cat("TEST 5: FAIL\n\n")
  }

  # Test 6: Non-log-concave function (should fail)
  cat("TEST 6: Non-log-concave function detection\n")
  test6_passed <- FALSE

  # A bimodal distribution is not log-concave
  bimodal <- function(x) 0.5 * dnorm(x, -2, 0.5) + 0.5 * dnorm(x, 2, 0.5)

  tryCatch({
    samples_bad <- ars(100, bimodal, domain = c(-10, 10),
                       x_init = c(-3, -1, 0, 1, 3))
    cat("  - WARNING: Failed to detect non-log-concave function\n")
  }, error = function(e) {
    cat("  - Correctly detected non-log-concave function\n")
    cat("  - Error message:", conditionMessage(e), "\n")
    test6_passed <<- TRUE
  })

  if (test6_passed) {
    cat("TEST 6: PASS\n\n")
  } else {
    cat("TEST 6: FAIL\n\n")
  }

  # Summary
  cat("========================================\n")
  cat("TEST SUMMARY\n")
  cat("========================================\n")
  all_passed <- test1_passed && test2_passed && test3_passed && 
                test4_passed && test5_passed && test6_passed

  if (all_passed) {
    cat("ALL TESTS PASSED\n")
  } else {
    cat("SOME TESTS FAILED\n")
    cat("  Test 1 (Input validation):", ifelse(test1_passed, "PASS", "FAIL"), "\n")
    cat("  Test 2 (Normal distribution):", ifelse(test2_passed, "PASS", "FAIL"), "\n")
    cat("  Test 3 (Exponential distribution):", ifelse(test3_passed, "PASS", "FAIL"), "\n")
    cat("  Test 4 (Gamma distribution):", ifelse(test4_passed, "PASS", "FAIL"), "\n")
    cat("  Test 5 (Beta distribution):", ifelse(test5_passed, "PASS", "FAIL"), "\n")
    cat("  Test 6 (Non-log-concave detection):", ifelse(test6_passed, "PASS", "FAIL"), "\n")
  }
  cat("========================================\n\n")

  invisible(all_passed)
}

